using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
namespace CoopBeam {
// Explicitly run in Play Mode only; never saved into scenes.
public class FirePlayModeQA:MonoBehaviour {
 List<string> lines=new List<string>();int failed;GameManager game;LinkPowers powers;int maxHazards;
 void Check(bool value,string label){lines.Add((value?"PASS ":"FAIL ")+label);if(!value)failed++;}
 EnemyBase Dummy(Vector2 point){var e=Instantiate(game.enemyPrefabs[0],point,Quaternion.identity);e.GetComponent<FireEnemyBrain>().enabled=false;e.GetComponent<Rigidbody2D>().bodyType=RigidbodyType2D.Kinematic;game.enemies.Add(e);return e;}
 void Observe(){maxHazards=Mathf.Max(maxHazards,EncounterHazard.LiveCount);}
 IEnumerator Start(){game=GameManager.Instance;powers=game.GetComponent<LinkPowers>();game.GetComponent<CandyLevelExit>().enabled=false;game.Begin();game.StopAllCoroutines();foreach(var h in game.players){h.Protect(2000);h.GetComponent<PlayerController2D>().enabled=false;h.GetComponent<Rigidbody2D>().bodyType=RigidbodyType2D.Kinematic;h.transform.position=new Vector3(h==game.players[0]?-8:8,5,0);}yield return null;
  var jumper=Instantiate(game.players[0],Vector3.zero,Quaternion.identity);jumper.GetComponent<PlayerController2D>().enabled=false;var jumpBody=jumper.GetComponent<Rigidbody2D>();jumpBody.bodyType=RigidbodyType2D.Dynamic;jumpBody.gravityScale=3;var jumpShape=jumper.GetComponent<Collider2D>();var floor=GameObject.Find("Obsidian foundation").GetComponent<Collider2D>();var mid=GameObject.Find("Forge gallery west").GetComponent<Collider2D>();var upper=GameObject.Find("Sun wheel west").GetComponent<Collider2D>();jumpBody.position=new Vector2(-6,floor.bounds.max.y+jumpShape.bounds.extents.y+.02f);jumpBody.linearVelocity=new Vector2(0,13);yield return new WaitForSeconds(.8f);Check(jumpShape.bounds.min.y>=mid.bounds.max.y-.08f&&Mathf.Abs(jumpBody.linearVelocity.y)<.1f,"Real physics jump reaches boss mid gallery");jumpBody.position=new Vector2(-6,mid.bounds.max.y+jumpShape.bounds.extents.y+.02f);jumpBody.linearVelocity=new Vector2(1.7f,13);yield return new WaitForSeconds(.8f);Check(jumpShape.bounds.min.y>=upper.bounds.max.y-.08f&&Mathf.Abs(jumpBody.linearVelocity.y)<.1f,"Real physics jump reaches boss upper gallery");Destroy(jumper.gameObject);yield return null;
  var lootEnemy=Dummy(Vector2.zero);yield return null;lootEnemy.Damage(1000);yield return null;var pickups=FindObjectsByType<LinkPickup>();Check(pickups.Length==1,"First kill visibly drops loot");var pickup=pickups[0];Check(!pickup.Ready&&!pickup.TryCollect(),"Reveal delay prevents instant ray collection");Check(pickup.GetComponent<SpriteRenderer>()&&pickup.GetComponent<SpriteRenderer>().sprite,"Dropped loot has visible sprite");yield return new WaitForSeconds(1.3f);Check(pickup&&pickup.Ready,"Loot becomes collectible after reveal");int before=powers.PickupsCollected;Check(pickup.TryCollect()&&powers.PickupsCollected==before+1,"Visible loot grants its actual effect");yield return null;
  for(int i=0;i<5;i++)powers.OnKill(new Vector3(i-2,0,0));yield return null;pickups=FindObjectsByType<LinkPickup>();var kinds=new HashSet<LinkPickup.Kind>();foreach(var p in pickups)kinds.Add(p.kind);Check(kinds.Count==5,"Kills rotate through all five powers");foreach(var p in pickups)Destroy(p.gameObject);yield return null;
  // Actual ray collection, with the players far from the icon themselves.
  game.players[0].transform.position=new Vector3(-8,4,0);game.players[1].transform.position=new Vector3(8,4,0);var rayPickup=LinkPickup.Create(new Vector3(0,2.95f,0),LinkPickup.Kind.Shield);rayPickup.owner=powers;yield return new WaitForSeconds(1.5f);Check(!rayPickup,"Ray collects revealed loot without player contact");
  game.players[0].transform.position=new Vector3(-8,3,0);game.players[1].transform.position=new Vector3(8,3,0);var beam=FindAnyObjectByType<CoopBeam>();var source=Dummy(Vector2.zero);var near=Dummy(new Vector2(2.3f,0));var far=Dummy(new Vector2(6.2f,0));yield return null;Physics2D.SyncTransforms();powers.Collect(LinkPickup.Kind.Chain);float nearHP=near.Health,farHP=far.Health;beam.DamageSegment(new Vector2(-1.5f,0),new Vector2(1.5f,0),.05f);Check(Mathf.Abs(nearHP-near.Health-10)<.01f,"Chain damages a nearby enemy outside the original ray");Check(far.Health==farHP,"Chain respects its range");nearHP=near.Health;beam.DamageSegment(new Vector2(-1.5f,0),new Vector2(1.5f,0),.05f);Check(near.Health==nearHP,"Chain cooldown prevents damage per collider/frame");source.FinishDeath();near.FinishDeath();far.FinishDeath();yield return new WaitForSeconds(.5f);
  var solarTarget=Dummy(new Vector2(0,2.2f));yield return null;powers.Collect(LinkPickup.Kind.Solar);float solarHP=solarTarget.Health;yield return new WaitForSeconds(.6f);Check(solarTarget.Health<solarHP&&powers.SolarHits>0,"Solar pulse damages enemies near but not on the thin ray");solarTarget.FinishDeath();yield return new WaitForSeconds(.5f);
  var fiery=FireHazard.Spawn(new Vector2(0,0),Vector2.one,.5f,.5f,Vector2.zero,this,1,false);Check(fiery&&!fiery.Active&&!fiery.GetComponent<Collider2D>().enabled,"Fire warning has no damaging collider");yield return new WaitForSeconds(.65f);Check(fiery&&fiery.Active&&fiery.GetComponent<Collider2D>().enabled,"Fire becomes damaging after cyan warning");yield return new WaitForSeconds(.5f);Check(!fiery,"Fire hazard expires");
  game.players[0].transform.position=new Vector3(-10,5,0);game.players[1].transform.position=new Vector3(10,5,0);
  for(int role=0;role<6;role++){var enemy=Instantiate(game.enemyPrefabs[role],new Vector2(0,role==3?2:-3.6f),Quaternion.identity);game.enemies.Add(enemy);yield return null;var ai=enemy.GetComponent<FireEnemyBrain>();Check(ai!=null,"Fire role "+role+" has dedicated brain");float limit=Time.time+7;while(ai.AttacksPerformed==0&&Time.time<limit){Observe();yield return null;}Check(ai.AttacksPerformed>0,"Fire role "+role+" performs its announced attack");if(role==1){limit=Time.time+4;while(!ai.Recovering&&Time.time<limit)yield return null;float hp=enemy.Health;enemy.Damage(10);Check(ai.Recovering&&Mathf.Abs(hp-enemy.Health-10)<.01f,"Basalt beetle exposes armor during recovery");}enemy.FinishDeath();yield return new WaitForSeconds(.55f);}
  foreach(var remainingPickup in FindObjectsByType<LinkPickup>())Destroy(remainingPickup.gameObject);yield return null;var bossEnemy=Instantiate(game.enemyPrefabs[6],new Vector2(0,-2.65f),Quaternion.identity);game.enemies.Add(bossEnemy);yield return null;var boss=bossEnemy.GetComponent<FireForgeBoss>();float initial=bossEnemy.Health;bossEnemy.Damage(100);Check(bossEnemy.Health==initial,"Closed furnace blocks direct damage");game.players[0].transform.position=new Vector3(-5,-2.45f,0);game.players[1].transform.position=new Vector3(5,-2.45f,0);powers.Collect(LinkPickup.Kind.Solar);float charge=powers.Charge;beam.DamageSegment(new Vector2(-3,-2.45f),new Vector2(3,-2.45f),1);yield return new WaitForSeconds(.65f);Check(bossEnemy.Health==initial,"Solar pulse respects the closed furnace");Check(powers.Charge==charge,"Blocked boss damage cannot charge ultimate");game.players[0].transform.position=new Vector3(-10,5,0);game.players[1].transform.position=new Vector3(10,5,0);
  for(int phase=1;phase<=3;phase++){for(int pattern=0;pattern<5;pattern++){float limit=Time.time+22;while((boss.Phase!=phase||!boss.Vulnerable||boss.PatternIndex!=pattern)&&Time.time<limit){Observe();yield return null;}Check(boss.Phase==phase&&boss.Vulnerable&&boss.PatternIndex==pattern,"Boss phase "+phase+" pattern "+pattern+" reaches recovery");}bossEnemy.Damage(100000);if(phase<3){Check(Mathf.Abs(bossEnemy.Health-bossEnemy.maxHealth*(phase==1?.7f:.35f))<.1f,"Cannot skip fire boss phase "+phase);yield return new WaitForSeconds(6.5f);Check(boss.Phase==phase+1,"Fire boss transforms to phase "+(phase+1));}else{Check(boss.Defeated,"Fire boss starts animated defeat");Check(game.enemies.Contains(bossEnemy),"Boss remains registered during defeat animation");yield return new WaitForSeconds(2.5f);Check(!game.enemies.Contains(bossEnemy),"Boss unregisters after defeat animation");}}
  Check(EncounterHazard.LiveCount==0,"Boss defeat cleans all its fire hazards");Check(maxHazards<=24,"Observed fire hazard count respects global cap");Time.timeScale=1;lines.Insert(0,"Fire Play Mode QA: "+(lines.Count-failed)+" PASS, "+failed+" FAIL. Accelerated traversal with protected players, not human balance certification.");File.WriteAllLines(Application.dataPath+"/ReinoDeFuego/0_6_QA/FirePlayMode.txt",lines);Debug.Log("FIRE_QA_DONE "+lines[0]);
 }
 void OnDestroy(){Time.timeScale=1;}
}
}
